per_hop.query:
SELECT DISTINCT ?actor WHERE {
  ?wonderWomanMovie wdt:P31 wd:Q11424;         # instance of film
                     rdfs:label "Wonder Woman"@en;
                     wdt:P577 ?wwReleaseDate;
                     wdt:P345 ?wwIMDbID.
  FILTER(year(?wwReleaseDate) = 2017)
  ?wonderWomanMovie wdt:P161 ?actor.

  ?actor wdt:P569 ?birthDate.

  ?anomalisa wdt:P31 wd:Q11424;
            rdfs:label "Anomalisa"@en;
            wdt:P161 ?actor;
            wdt:P577 ?anomalisaDate.

  ?fargoSeries wdt:P31 wd:Q5398426;            # instance of TV series
               rdfs:label "Fargo"@en;
               wdt:P580 ?fargoPremiereDate.

  FILTER(?anomalisaDate > ?fargoPremiereDate)
}
LIMIT 10
